CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260606224250_InitialCreate') THEN
    CREATE TABLE "Albums" (
        "AlbumId" integer GENERATED BY DEFAULT AS IDENTITY,
        "ReleaseDate" timestamp with time zone,
        "Title" character varying(200) NOT NULL,
        "NumberOfSongs" integer NOT NULL,
        CONSTRAINT "PK_Albums" PRIMARY KEY ("AlbumId")
    );
    END IF;
END $EF$;

